#!/usr/bin/env python3
"""pyaot — single-file ahead-of-time Python static checker + C compiler.

Usage:
    python pyaot.py file.py            # check one file
    python pyaot.py somedir/           # check every .py under a directory
    python pyaot.py file.py -o prog    # check + compile to native binary
    python pyaot.py file.py --emit-c   # dump generated C
"""
from __future__ import annotations
import argparse, ast, builtins as _builtins, os, subprocess, sys, tempfile
from dataclasses import dataclass, field
from enum import Enum
from typing import Optional

# ===== from pyaot/types.py =====
"""Type system for the pyaot ahead-of-time checker/compiler.

Types are immutable value objects with structural equality. They model a
statically-typed subset of Python. ``Any`` is the escape hatch and is
compatible with everything (gradual typing).
"""




class Type:
    """Base class for all types."""

    def __str__(self) -> str:  # pragma: no cover - overridden
        return self.__class__.__name__

    def __repr__(self) -> str:
        return str(self)


@dataclass(frozen=True)
class AnyType(Type):
    def __str__(self) -> str:
        return "Any"


@dataclass(frozen=True)
class NoneType(Type):
    def __str__(self) -> str:
        return "None"


@dataclass(frozen=True)
class IntType(Type):
    def __str__(self) -> str:
        return "int"


@dataclass(frozen=True)
class FloatType(Type):
    def __str__(self) -> str:
        return "float"


@dataclass(frozen=True)
class BoolType(Type):
    def __str__(self) -> str:
        return "bool"


@dataclass(frozen=True)
class StrType(Type):
    def __str__(self) -> str:
        return "str"


@dataclass(frozen=True)
class NeverType(Type):
    """The type of expressions that never produce a value (e.g. raise)."""

    def __str__(self) -> str:
        return "Never"


@dataclass(frozen=True)
class ListType(Type):
    elem: Type

    def __str__(self) -> str:
        return f"list[{self.elem}]"


@dataclass(frozen=True)
class DictType(Type):
    key: Type
    value: Type

    def __str__(self) -> str:
        return f"dict[{self.key}, {self.value}]"


@dataclass(frozen=True)
class TupleType(Type):
    elems: tuple[Type, ...]

    def __str__(self) -> str:
        inner = ", ".join(str(e) for e in self.elems)
        return f"tuple[{inner}]"


@dataclass(frozen=True)
class OptionalType(Type):
    """``Optional[T]`` == ``T | None``."""

    inner: Type

    def __str__(self) -> str:
        return f"Optional[{self.inner}]"


@dataclass(frozen=True)
class UnionType(Type):
    options: tuple[Type, ...]

    def __str__(self) -> str:
        return " | ".join(str(o) for o in self.options)


@dataclass(frozen=True)
class FunctionType(Type):
    params: tuple[Type, ...]
    ret: Type
    param_names: tuple[str, ...] = ()
    defaults: int = 0  # number of trailing params that have defaults

    def __str__(self) -> str:
        ps = ", ".join(str(p) for p in self.params)
        return f"({ps}) -> {self.ret}"


# Singletons for the common ground types.
ANY = AnyType()
NONE = NoneType()
INT = IntType()
FLOAT = FloatType()
BOOL = BoolType()
STR = StrType()
NEVER = NeverType()


def is_any(t: Type) -> bool:
    return isinstance(t, AnyType)


def make_optional(t: Type) -> Type:
    if isinstance(t, OptionalType):
        return t
    if isinstance(t, NoneType):
        return t
    return OptionalType(t)


def make_union(options: list[Type]) -> Type:
    """Build a normalized union: flatten, dedup, collapse singletons."""
    flat: list[Type] = []

    def add(x: Type) -> None:
        if isinstance(x, UnionType):
            for o in x.options:
                add(o)
        elif isinstance(x, OptionalType):
            add(x.inner)
            add(NONE)
        else:
            if x not in flat:
                flat.append(x)

    for o in options:
        add(o)

    if len(flat) == 1:
        return flat[0]
    # Collapse T | None into Optional[T] when exactly two members.
    if len(flat) == 2 and NONE in flat:
        other = flat[0] if flat[1] == NONE else flat[1]
        return OptionalType(other)
    return UnionType(tuple(flat))

# ===== from pyaot/subtype.py =====
"""Assignability (subtyping) rules for the type system.

``is_assignable(src, dst)`` answers: can a value of type ``src`` be used
where a value of type ``dst`` is expected?
"""




def is_assignable(src: Type, dst: Type) -> bool:
    # Any is compatible in both directions (gradual typing).
    if isinstance(src, AnyType) or isinstance(dst, AnyType):
        return True

    # Never is assignable to anything (bottom type).
    if isinstance(src, NeverType):
        return True

    # Exact structural equality always works.
    if src == dst:
        return True

    # bool is a subtype of int (as in Python).
    if isinstance(src, BoolType) and isinstance(dst, IntType):
        return True

    # int is assignable to float (numeric widening).
    if isinstance(src, IntType) and isinstance(dst, FloatType):
        return True
    if isinstance(src, BoolType) and isinstance(dst, FloatType):
        return True

    # None into Optional / unions handled below.
    if isinstance(dst, OptionalType):
        if isinstance(src, NoneType):
            return True
        return is_assignable(src, dst.inner)

    if isinstance(src, OptionalType):
        # Optional[T] assignable to U only if both T and None are.
        return is_assignable(src.inner, dst) and is_assignable(NONE, dst)

    if isinstance(dst, UnionType):
        return any(is_assignable(src, o) for o in dst.options)

    if isinstance(src, UnionType):
        return all(is_assignable(o, dst) for o in src.options)

    # Containers: invariant on element type, but Any/Never give flexibility,
    # and an empty literal yields elem == Never so it fits any list.
    if isinstance(src, ListType) and isinstance(dst, ListType):
        return is_assignable(src.elem, dst.elem)

    if isinstance(src, DictType) and isinstance(dst, DictType):
        return is_assignable(src.key, dst.key) and is_assignable(
            src.value, dst.value
        )

    if isinstance(src, TupleType) and isinstance(dst, TupleType):
        if len(src.elems) != len(dst.elems):
            return False
        return all(is_assignable(a, b) for a, b in zip(src.elems, dst.elems))

    if isinstance(src, FunctionType) and isinstance(dst, FunctionType):
        if len(src.params) != len(dst.params):
            return False
        # Params contravariant, return covariant.
        if not all(is_assignable(dp, sp) for sp, dp in zip(src.params, dst.params)):
            return False
        return is_assignable(src.ret, dst.ret)

    return False


def join(a: Type, b: Type) -> Type:
    """Least common supertype for if/else branch merging."""
    pass

    if a == b:
        return a
    if isinstance(a, AnyType) or isinstance(b, AnyType):
        return ANY
    if isinstance(a, NeverType):
        return b
    if isinstance(b, NeverType):
        return a
    if is_assignable(a, b):
        return b
    if is_assignable(b, a):
        return a
    return make_union([a, b])

# ===== from pyaot/annotations.py =====
"""Resolve Python annotation AST nodes into our Type objects."""




_SIMPLE = {
    "int": INT,
    "float": FLOAT,
    "bool": BOOL,
    "str": STR,
    "None": NONE,
    "Any": ANY,
    "object": ANY,
}


def resolve_annotation(node: ast.expr | None) -> Type:
    """Best-effort: unknown annotations resolve to Any."""
    if node is None:
        return ANY

    if isinstance(node, ast.Name):
        return _SIMPLE.get(node.id, ANY)

    if isinstance(node, ast.Constant):
        if node.value is None:
            return NONE
        if isinstance(node.value, str):
            # Forward-ref string, e.g. "int"; try to parse it.
            try:
                inner = ast.parse(node.value, mode="eval").body
                return resolve_annotation(inner)
            except SyntaxError:
                return ANY
        return ANY

    if isinstance(node, ast.Subscript):
        return _resolve_subscript(node)

    # PEP 604 unions: int | None
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitOr):
        left = resolve_annotation(node.left)
        right = resolve_annotation(node.right)
        return make_union([left, right])

    return ANY


def _base_name(node: ast.expr) -> str:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    return ""


def _resolve_subscript(node: ast.Subscript) -> Type:
    base = _base_name(node.value).lower()
    sl = node.slice

    if base == "list":
        return ListType(resolve_annotation(sl))
    if base == "dict":
        if isinstance(sl, ast.Tuple) and len(sl.elts) == 2:
            return DictType(
                resolve_annotation(sl.elts[0]), resolve_annotation(sl.elts[1])
            )
        return DictType(ANY, ANY)
    if base == "tuple":
        if isinstance(sl, ast.Tuple):
            return TupleType(tuple(resolve_annotation(e) for e in sl.elts))
        return TupleType((resolve_annotation(sl),))
    if base == "optional":
        return make_optional(resolve_annotation(sl))
    if base == "union":
        if isinstance(sl, ast.Tuple):
            return make_union([resolve_annotation(e) for e in sl.elts])
        return resolve_annotation(sl)
    return ANY

# ===== from pyaot/diagnostics.py =====
"""Rust-style diagnostics: errors collected ahead of time with source spans."""




class Severity(Enum):
    ERROR = "error"
    WARNING = "warning"


@dataclass
class Diagnostic:
    severity: Severity
    code: str          # e.g. "E0001"
    message: str
    line: int
    col: int
    note: str | None = None

    def __str__(self) -> str:
        s = f"{self.severity.value}[{self.code}]: {self.message}"
        s += f"\n  --> line {self.line}:{self.col}"
        if self.note:
            s += f"\n  = note: {self.note}"
        return s


class DiagnosticBag:
    def __init__(self, source: str = "", filename: str = "<input>") -> None:
        self.diags: list[Diagnostic] = []
        self.source_lines = source.splitlines()
        self.filename = filename

    def error(self, code: str, message: str, node, note: str | None = None) -> None:
        self.diags.append(
            Diagnostic(
                Severity.ERROR,
                code,
                message,
                getattr(node, "lineno", 0),
                getattr(node, "col_offset", 0) + 1,
                note,
            )
        )

    def warning(self, code: str, message: str, node, note: str | None = None) -> None:
        self.diags.append(
            Diagnostic(
                Severity.WARNING,
                code,
                message,
                getattr(node, "lineno", 0),
                getattr(node, "col_offset", 0) + 1,
                note,
            )
        )

    @property
    def errors(self) -> list[Diagnostic]:
        return [d for d in self.diags if d.severity == Severity.ERROR]

    @property
    def has_errors(self) -> bool:
        return any(d.severity == Severity.ERROR for d in self.diags)

    def render(self) -> str:
        out = []
        # Stable order by position.
        for d in sorted(self.diags, key=lambda x: (x.line, x.col)):
            out.append(self._render_one(d))
        return "\n\n".join(out)

    def _render_one(self, d: Diagnostic) -> str:
        head = f"{d.severity.value}[{d.code}]: {d.message}"
        loc = f"  --> {self.filename}:{d.line}:{d.col}"
        lines = [head, loc]
        if 1 <= d.line <= len(self.source_lines):
            src = self.source_lines[d.line - 1]
            gutter = f"{d.line} | "
            lines.append(f"   |")
            lines.append(f" {gutter}{src}")
            caret = " " * (len(gutter) + max(0, d.col - 1)) + "^"
            lines.append(f"   | {caret}")
        if d.note:
            lines.append(f"   = note: {d.note}")
        return "\n".join(lines)

# ===== from pyaot/codegen.py =====
"""Ahead-of-time code generation: compile a typed Python subset to C.

This is intentionally a *subset*. Anything outside it raises
``UnsupportedError`` with a clear message rather than emitting wrong code.
The checker runs first, so by the time we get here the program is known to be
type-correct; codegen only has to translate, not validate types.

Supported: top-level annotated ``def``s with int/float/bool/str params and
return types; int/float/bool/str locals; arithmetic, comparison, boolean and
unary ops; ``if/elif/else``; ``while``; ``for i in range(...)``; ``return``;
recursion; and ``print()`` of a single int/float/bool/str value.
"""





class UnsupportedError(Exception):
    def __init__(self, msg: str, node: ast.AST | None = None):
        line = getattr(node, "lineno", "?")
        super().__init__(f"line {line}: {msg}")
        self.node = node


_CTYPE = {
    "int": "long",
    "float": "double",
    "bool": "int",
    "str": "const char*",
    "None": "void",
}


def _ctype(t: Type) -> str:
    if isinstance(t, IntType):
        return "long"
    if isinstance(t, FloatType):
        return "double"
    if isinstance(t, BoolType):
        return "int"
    if isinstance(t, StrType):
        return "const char*"
    if isinstance(t, NoneType):
        return "void"
    raise UnsupportedError(f"type '{t}' is not supported by the C backend")


class CodeGen:
    def __init__(self, tree: ast.Module):
        self.tree = tree
        self.lines: list[str] = []
        self.indent = 0
        # name -> Type, per function.
        self.locals: dict[str, Type] = {}
        self.funcs: dict[str, ast.FunctionDef] = {}

    def emit(self, line: str) -> None:
        self.lines.append("    " * self.indent + line)

    # -- module ---------------------------------------------------------
    def generate(self) -> str:
        self.emit("#include <stdio.h>")
        self.emit("#include <stdlib.h>")
        self.emit("#include <string.h>")
        self.emit("#include <math.h>")
        self.emit("")

        funcs = [s for s in self.tree.body if isinstance(s, ast.FunctionDef)]
        for fn in funcs:
            self.funcs[fn.name] = fn

        # Forward declarations so order/recursion don't matter.
        for fn in funcs:
            self.emit(self._signature(fn) + ";")
        self.emit("")

        for fn in funcs:
            self._gen_function(fn)
            self.emit("")

        if "main" not in self.funcs:
            raise UnsupportedError("program needs a 'main' function as entry point")
        ret = resolve_annotation(self.funcs["main"].returns)
        self.emit("int main(void) {")
        self.indent += 1
        self.emit("py_main();")
        self.emit("return 0;")
        self.indent -= 1
        self.emit("}")
        return "\n".join(self.lines) + "\n"

    def _cname(self, name: str) -> str:
        return "py_" + name

    def _signature(self, fn: ast.FunctionDef) -> str:
        ret = _ctype(resolve_annotation(fn.returns))
        params = []
        for a in fn.args.args:
            if a.annotation is None:
                raise UnsupportedError(
                    f"parameter '{a.arg}' must be annotated", fn)
            params.append(f"{_ctype(resolve_annotation(a.annotation))} {a.arg}")
        plist = ", ".join(params) if params else "void"
        return f"{ret} {self._cname(fn.name)}({plist})"

    def _gen_function(self, fn: ast.FunctionDef) -> None:
        if fn.args.vararg or fn.args.kwarg or fn.args.kwonlyargs:
            raise UnsupportedError("varargs/kwargs not supported", fn)
        if fn.args.defaults:
            raise UnsupportedError("default arguments not supported by backend", fn)
        self.locals = {}
        for a in fn.args.args:
            self.locals[a.arg] = resolve_annotation(a.annotation)
        self.emit(self._signature(fn) + " {")
        self.indent += 1
        # Pre-declare locals discovered by a quick scan.
        self._declare_locals(fn)
        for stmt in fn.body:
            self._gen_stmt(stmt)
        self.indent -= 1
        self.emit("}")

    def _declare_locals(self, fn: ast.FunctionDef) -> None:
        seen = set(self.locals)
        for node in ast.walk(fn):
            if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                name = node.target.id
                if name not in seen:
                    t = resolve_annotation(node.annotation)
                    self.locals[name] = t
                    self.emit(f"{_ctype(t)} {name};")
                    seen.add(name)
            elif isinstance(node, ast.Assign):
                for tgt in node.targets:
                    if isinstance(tgt, ast.Name) and tgt.id not in seen:
                        t = self._infer(node.value)
                        self.locals[tgt.id] = t
                        self.emit(f"{_ctype(t)} {tgt.id};")
                        seen.add(tgt.id)
            elif isinstance(node, ast.For):
                if isinstance(node.target, ast.Name) and node.target.id not in seen:
                    self.locals[node.target.id] = INT
                    self.emit(f"long {node.target.id};")
                    seen.add(node.target.id)

    # -- statements -----------------------------------------------------
    def _gen_stmt(self, stmt: ast.stmt) -> None:
        m = getattr(self, "_stmt_" + type(stmt).__name__, None)
        if m is None:
            raise UnsupportedError(
                f"statement '{type(stmt).__name__}' not supported by C backend",
                stmt,
            )
        m(stmt)

    def _stmt_Return(self, stmt: ast.Return) -> None:
        if stmt.value is None:
            self.emit("return;")
        else:
            self.emit(f"return {self._gen_expr(stmt.value)};")

    def _stmt_Assign(self, stmt: ast.Assign) -> None:
        if len(stmt.targets) != 1 or not isinstance(stmt.targets[0], ast.Name):
            raise UnsupportedError("only simple 'name = expr' assignment", stmt)
        name = stmt.targets[0].id
        self.emit(f"{name} = {self._gen_expr(stmt.value)};")

    def _stmt_AnnAssign(self, stmt: ast.AnnAssign) -> None:
        if not isinstance(stmt.target, ast.Name):
            raise UnsupportedError("only simple annotated assignment", stmt)
        if stmt.value is not None:
            self.emit(f"{stmt.target.id} = {self._gen_expr(stmt.value)};")

    def _stmt_AugAssign(self, stmt: ast.AugAssign) -> None:
        if not isinstance(stmt.target, ast.Name):
            raise UnsupportedError("only simple augmented assignment", stmt)
        op = self._binop_sym(stmt.op)
        self.emit(f"{stmt.target.id} {op}= {self._gen_expr(stmt.value)};")

    def _stmt_If(self, stmt: ast.If) -> None:
        self.emit(f"if ({self._gen_expr(stmt.test)}) {{")
        self.indent += 1
        for s in stmt.body:
            self._gen_stmt(s)
        self.indent -= 1
        if stmt.orelse:
            self.emit("} else {")
            self.indent += 1
            for s in stmt.orelse:
                self._gen_stmt(s)
            self.indent -= 1
        self.emit("}")

    def _stmt_While(self, stmt: ast.While) -> None:
        self.emit(f"while ({self._gen_expr(stmt.test)}) {{")
        self.indent += 1
        for s in stmt.body:
            self._gen_stmt(s)
        self.indent -= 1
        self.emit("}")

    def _stmt_For(self, stmt: ast.For) -> None:
        if not isinstance(stmt.target, ast.Name):
            raise UnsupportedError("for-target must be a simple name", stmt)
        rng = self._range_bounds(stmt.iter)
        if rng is None:
            raise UnsupportedError("only 'for i in range(...)' is supported", stmt)
        var = stmt.target.id
        start, stop, step = rng
        if step.startswith("-") or step.lstrip("-").isdigit() and int(step) < 0:
            cmp = ">"
        else:
            cmp = "<"
        self.emit(
            f"for ({var} = {start}; {var} {cmp} {stop}; {var} += {step}) {{"
        )
        self.indent += 1
        for s in stmt.body:
            self._gen_stmt(s)
        self.indent -= 1
        self.emit("}")

    def _stmt_Expr(self, stmt: ast.Expr) -> None:
        # Only print() calls and bare calls produce side effects we emit.
        if isinstance(stmt.value, ast.Call):
            self.emit(self._gen_call(stmt.value, as_stmt=True) + ";")
        else:
            # Pure expression statement: no effect, skip.
            pass

    def _stmt_Pass(self, stmt) -> None:
        self.emit(";")

    def _stmt_Break(self, stmt) -> None:
        self.emit("break;")

    def _stmt_Continue(self, stmt) -> None:
        self.emit("continue;")

    def _range_bounds(self, node: ast.expr):
        if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == "range"):
            return None
        args = [self._gen_expr(a) for a in node.args]
        if len(args) == 1:
            return ("0", args[0], "1")
        if len(args) == 2:
            return (args[0], args[1], "1")
        if len(args) == 3:
            return (args[0], args[1], args[2])
        raise UnsupportedError("range() takes 1-3 args", node)

    # -- expressions ----------------------------------------------------
    def _gen_expr(self, node: ast.expr) -> str:
        m = getattr(self, "_e_" + type(node).__name__, None)
        if m is None:
            raise UnsupportedError(
                f"expression '{type(node).__name__}' not supported by C backend",
                node,
            )
        return m(node)

    def _e_Constant(self, node: ast.Constant) -> str:
        v = node.value
        if isinstance(v, bool):
            return "1" if v else "0"
        if isinstance(v, int):
            return f"{v}L"
        if isinstance(v, float):
            return repr(v)
        if isinstance(v, str):
            return self._c_string(v)
        raise UnsupportedError(f"constant {v!r} not supported", node)

    def _c_string(self, s: str) -> str:
        esc = (
            s.replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\n", "\\n")
            .replace("\t", "\\t")
            .replace("\r", "\\r")
        )
        return f'"{esc}"'

    def _e_Name(self, node: ast.Name) -> str:
        if node.id in ("True",):
            return "1"
        if node.id in ("False",):
            return "0"
        return node.id

    def _e_BinOp(self, node: ast.BinOp) -> str:
        left = self._gen_expr(node.left)
        right = self._gen_expr(node.right)
        if isinstance(node.op, ast.Pow):
            return f"pow({left}, {right})"
        if isinstance(node.op, ast.FloorDiv):
            return f"(long)(({left}) / ({right}))"
        if isinstance(node.op, ast.Div):
            # Python '/' is always true division -> force double.
            return f"((double)({left}) / (double)({right}))"
        sym = self._binop_sym(node.op)
        return f"({left} {sym} {right})"

    def _binop_sym(self, op) -> str:
        mapping = {
            ast.Add: "+", ast.Sub: "-", ast.Mult: "*", ast.Div: "/",
            ast.Mod: "%", ast.BitOr: "|", ast.BitAnd: "&", ast.BitXor: "^",
            ast.LShift: "<<", ast.RShift: ">>",
        }
        for k, v in mapping.items():
            if isinstance(op, k):
                return v
        raise UnsupportedError(f"operator {type(op).__name__} not supported")

    def _e_UnaryOp(self, node: ast.UnaryOp) -> str:
        operand = self._gen_expr(node.operand)
        if isinstance(node.op, ast.USub):
            return f"(-{operand})"
        if isinstance(node.op, ast.UAdd):
            return f"(+{operand})"
        if isinstance(node.op, ast.Not):
            return f"(!{operand})"
        if isinstance(node.op, ast.Invert):
            return f"(~{operand})"
        raise UnsupportedError("unary op not supported", node)

    def _e_BoolOp(self, node: ast.BoolOp) -> str:
        sym = "&&" if isinstance(node.op, ast.And) else "||"
        parts = [self._gen_expr(v) for v in node.values]
        return "(" + f" {sym} ".join(parts) + ")"

    def _e_Compare(self, node: ast.Compare) -> str:
        if len(node.ops) != 1:
            # Expand chained comparisons a<b<c into (a<b)&&(b<c).
            parts = []
            left = node.left
            for op, comp in zip(node.ops, node.comparators):
                parts.append(self._compare_one(left, op, comp))
                left = comp
            return "(" + " && ".join(parts) + ")"
        return self._compare_one(node.left, node.ops[0], node.comparators[0])

    def _compare_one(self, left, op, right) -> str:
        l = self._gen_expr(left)
        r = self._gen_expr(right)
        sym = {
            ast.Lt: "<", ast.LtE: "<=", ast.Gt: ">", ast.GtE: ">=",
            ast.Eq: "==", ast.NotEq: "!=",
        }
        for k, v in sym.items():
            if isinstance(op, k):
                # String equality uses strcmp.
                if isinstance(op, (ast.Eq, ast.NotEq)) and (
                    self._is_str(left) or self._is_str(right)
                ):
                    base = f"strcmp({l}, {r})"
                    return f"({base} {v} 0)"
                return f"({l} {v} {r})"
        raise UnsupportedError("comparison operator not supported")

    def _e_IfExp(self, node: ast.IfExp) -> str:
        return (f"({self._gen_expr(node.test)} ? {self._gen_expr(node.body)} "
                f": {self._gen_expr(node.orelse)})")

    def _e_Call(self, node: ast.Call) -> str:
        return self._gen_call(node)

    def _gen_call(self, node: ast.Call, as_stmt: bool = False) -> str:
        if isinstance(node.func, ast.Name):
            name = node.func.id
            if name == "print":
                return self._gen_print(node)
            if name in ("int", "float", "bool"):
                return self._gen_cast(name, node)
            if name == "len":
                if len(node.args) == 1:
                    return f"((long)strlen({self._gen_expr(node.args[0])}))"
            if name == "abs":
                a = self._gen_expr(node.args[0])
                return f"labs({a})"
            if name in self.funcs:
                args = ", ".join(self._gen_expr(a) for a in node.args)
                return f"{self._cname(name)}({args})"
            raise UnsupportedError(f"call to '{name}' not supported by backend", node)
        raise UnsupportedError("only direct function calls supported", node)

    def _gen_cast(self, name: str, node: ast.Call) -> str:
        a = self._gen_expr(node.args[0])
        if name == "int":
            return f"((long)({a}))"
        if name == "float":
            return f"((double)({a}))"
        if name == "bool":
            return f"(({a}) ? 1 : 0)"
        raise UnsupportedError("unsupported cast", node)

    def _gen_print(self, node: ast.Call) -> str:
        if len(node.args) == 0:
            return 'printf("\\n")'
        if len(node.args) != 1:
            raise UnsupportedError("print() supports a single argument", node)
        arg = node.args[0]
        t = self._infer(arg)
        expr = self._gen_expr(arg)
        if isinstance(t, IntType):
            return f'printf("%ld\\n", {expr})'
        if isinstance(t, BoolType):
            return f'printf("%s\\n", ({expr}) ? "True" : "False")'
        if isinstance(t, FloatType):
            return f'printf("%g\\n", {expr})'
        if isinstance(t, StrType):
            return f'printf("%s\\n", {expr})'
        raise UnsupportedError(f"cannot print value of type '{t}'", node)

    # -- local type inference (subset) ----------------------------------
    def _is_str(self, node: ast.expr) -> bool:
        return isinstance(self._infer(node), StrType)

    def _infer(self, node: ast.expr) -> Type:
        if isinstance(node, ast.Constant):
            v = node.value
            if isinstance(v, bool):
                return BOOL
            if isinstance(v, int):
                return INT
            if isinstance(v, float):
                return FLOAT
            if isinstance(v, str):
                return STR
            return INT
        if isinstance(node, ast.Name):
            if node.id in ("True", "False"):
                return BOOL
            return self.locals.get(node.id, INT)
        if isinstance(node, ast.BinOp):
            l = self._infer(node.left)
            r = self._infer(node.right)
            if isinstance(node.op, ast.Div):
                return FLOAT
            if isinstance(l, StrType) or isinstance(r, StrType):
                return STR
            if isinstance(l, FloatType) or isinstance(r, FloatType):
                return FLOAT
            return INT
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return BOOL
            return self._infer(node.operand)
        if isinstance(node, (ast.Compare, ast.BoolOp)):
            return BOOL
        if isinstance(node, ast.IfExp):
            return self._infer(node.body)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            name = node.func.id
            if name in ("int", "len", "abs", "ord"):
                return INT
            if name == "float":
                return FLOAT
            if name == "bool":
                return BOOL
            if name in ("str", "chr"):
                return STR
            if name in self.funcs:
                return resolve_annotation(self.funcs[name].returns)
        return INT


def compile_to_c(source: str, filename: str = "<input>") -> str:
    tree = ast.parse(source, filename)
    return CodeGen(tree).generate()

