"""The static checker: walks the AST ahead of time and reports bugs.

Design: lexical scopes, local type inference, and assignability checks.
Unknown things degrade to ``Any`` so we stay sound-ish without crashing on
unsupported syntax. The goal is zero false positives on the supported subset.
"""




# Builtins that return a known type when called.

# Every real builtin (functions, types, exceptions, True/False/None/...) plus
# the module-level dunders the interpreter injects into every module.
_KNOWN_NAMES = set(dir(_builtins)) | {
    "__name__", "__file__", "__doc__", "__package__", "__loader__",
    "__spec__", "__builtins__", "__dict__", "__path__", "__annotations__",
    "__cached__", "__class__", "self", "cls",
}

_BUILTIN_RETURNS = {
    "len": INT,
    "abs": ANY,
    "str": STR,
    "int": INT,
    "float": FLOAT,
    "bool": BOOL,
    "print": NONE,
    "repr": STR,
    "ord": INT,
    "chr": STR,
    "round": ANY,
    "input": STR,
}


class Scope:
    def __init__(self, parent: "Scope | None" = None, *, func_ret: Type | None = None):
        self.vars: dict[str, Type] = {}
        self.parent = parent
        # Expected return type if this scope is a function body.
        self.func_ret = func_ret if func_ret is not None else (
            parent.func_ret if parent else None
        )

    def lookup(self, name: str) -> Type | None:
        s: Scope | None = self
        while s is not None:
            if name in s.vars:
                return s.vars[name]
            s = s.parent
        return None

    def declared_here(self, name: str) -> bool:
        return name in self.vars

    def define(self, name: str, t: Type) -> None:
        self.vars[name] = t


class Checker:
    def __init__(self, source: str, filename: str = "<input>"):
        self.source = source
        self.bag = DiagnosticBag(source, filename)
        self.tree = ast.parse(source, filename)

    # -- entry point ----------------------------------------------------
    def check(self) -> DiagnosticBag:
        global_scope = Scope()
        self._predeclare(self.tree.body, global_scope)
        self._hoist_assigned(self.tree.body, global_scope)
        for stmt in self.tree.body:
            self._check_stmt(stmt, global_scope)
        return self.bag

    def _predeclare(self, body: list[ast.stmt], scope: Scope) -> None:
        """First pass: register function/class names for forward refs."""
        for stmt in body:
            if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
                scope.define(stmt.name, self._func_type(stmt))
            elif isinstance(stmt, ast.ClassDef):
                scope.define(stmt.name, ANY)

    def _hoist_assigned(self, body: list[ast.stmt], scope: Scope) -> None:
        """Predeclare every name bound anywhere in this scope as ``Any``.

        Python scoping is function/module-level, not block-level: a name
        assigned inside any branch, loop, ``with``, ``except`` or guarded
        ``import`` is in scope for the whole body. We pre-register those names
        so later uses are not falsely flagged as undefined. Precise types are
        still recovered when the actual binding is checked in source order.
        Nested function/class/lambda scopes are intentionally skipped.
        """
        for name in self._collect_bound_names(body):
            if not scope.declared_here(name):
                scope.define(name, ANY)

    def _collect_bound_names(self, body: list[ast.stmt]) -> set[str]:
        names: set[str] = set()

        def add_target(t: ast.expr) -> None:
            if isinstance(t, ast.Name):
                names.add(t.id)
            elif isinstance(t, (ast.Tuple, ast.List)):
                for e in t.elts:
                    add_target(e)
            elif isinstance(t, ast.Starred):
                add_target(t.value)

        def visit(node: ast.AST) -> None:
            for child in ast.iter_child_nodes(node):
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef,
                                      ast.ClassDef)):
                    names.add(child.name)  # the def/class name binds here
                    continue               # but its body is a new scope
                if isinstance(child, ast.Lambda):
                    continue
                if isinstance(child, ast.Assign):
                    for tgt in child.targets:
                        add_target(tgt)
                elif isinstance(child, (ast.AnnAssign, ast.AugAssign)):
                    add_target(child.target)
                elif isinstance(child, (ast.For, ast.AsyncFor)):
                    add_target(child.target)
                elif isinstance(child, ast.NamedExpr):
                    add_target(child.target)
                elif isinstance(child, (ast.Import, ast.ImportFrom)):
                    for alias in child.names:
                        if alias.name == "*":
                            continue
                        names.add(alias.asname or alias.name.split(".")[0])
                elif isinstance(child, ast.ExceptHandler) and child.name:
                    names.add(child.name)
                elif isinstance(child, ast.withitem):
                    if child.optional_vars is not None:
                        add_target(child.optional_vars)
                elif isinstance(child, (ast.Global, ast.Nonlocal)):
                    for n in child.names:
                        names.add(n)
                visit(child)

        for stmt in body:
            visit(stmt)
        return names

    def _func_type(self, fn: ast.FunctionDef) -> FunctionType:
        args = fn.args
        params = [resolve_annotation(a.annotation) for a in args.args]
        names = [a.arg for a in args.args]
        ret = resolve_annotation(fn.returns)
        return FunctionType(
            tuple(params), ret, tuple(names), len(args.defaults)
        )

    # -- statements -----------------------------------------------------
    def _check_block(self, body: list[ast.stmt], scope: Scope) -> bool:
        """Return True if the block definitely returns/raises on all paths."""
        terminated = False
        for i, stmt in enumerate(body):
            if terminated:
                self.bag.warning(
                    "W0001", "unreachable code", stmt,
                    "this statement can never execute",
                )
                # Still check it, but only warn once per block.
                terminated = True
            if self._check_stmt(stmt, scope):
                terminated = True
        return terminated

    def _check_stmt(self, stmt: ast.stmt, scope: Scope) -> bool:
        m = getattr(self, "_stmt_" + type(stmt).__name__, None)
        if m is None:
            # Unsupported statement: still walk expressions inside it.
            for child in ast.walk(stmt):
                if isinstance(child, ast.expr):
                    pass
            return False
        return m(stmt, scope)

    def _stmt_FunctionDef(self, fn: ast.FunctionDef, scope: Scope) -> bool:
        ftype = self._func_type(fn)
        scope.define(fn.name, ftype)
        body_scope = Scope(scope, func_ret=ftype.ret)
        for a, t in zip(fn.args.args, ftype.params):
            body_scope.define(a.arg, t)
        # vararg / kwarg
        if fn.args.vararg:
            body_scope.define(fn.args.vararg.arg, ANY)
        if fn.args.kwarg:
            body_scope.define(fn.args.kwarg.arg, ANY)
        for a in fn.args.kwonlyargs:
            body_scope.define(a.arg, resolve_annotation(a.annotation))
        self._predeclare(fn.body, body_scope)
        self._hoist_assigned(fn.body, body_scope)
        always_returns = self._check_block(fn.body, body_scope)
        # Check that a non-None return type is satisfied on all paths.
        ret = ftype.ret
        needs_value = not isinstance(ret, (NoneType, AnyType))
        if needs_value and not always_returns:
            self.bag.error(
                "E0011",
                f"function '{fn.name}' may not return a value on all paths "
                f"but is declared to return '{ret}'",
                fn,
                "add a return statement or change the return annotation",
            )
        return False

    _stmt_AsyncFunctionDef = _stmt_FunctionDef

    def _stmt_ClassDef(self, cls: ast.ClassDef, scope: Scope) -> bool:
        scope.define(cls.name, ANY)
        inner = Scope(scope)
        self._predeclare(cls.body, inner)
        for s in cls.body:
            self._check_stmt(s, inner)
        return False

    def _stmt_Return(self, ret: ast.Return, scope: Scope) -> bool:
        expected = scope.func_ret
        if ret.value is None:
            actual: Type = NONE
        else:
            actual = self._infer(ret.value, scope)
        if expected is not None and not isinstance(expected, AnyType):
            if not is_assignable(actual, expected):
                self.bag.error(
                    "E0005",
                    f"returning '{actual}' but function is declared to return "
                    f"'{expected}'",
                    ret,
                )
        return True

    def _stmt_Raise(self, raise_: ast.Raise, scope: Scope) -> bool:
        if raise_.exc is not None:
            self._infer(raise_.exc, scope)
        return True

    def _stmt_Pass(self, stmt, scope) -> bool:
        return False

    def _stmt_Break(self, stmt, scope) -> bool:
        return False

    def _stmt_Continue(self, stmt, scope) -> bool:
        return False

    def _stmt_Expr(self, stmt: ast.Expr, scope: Scope) -> bool:
        self._infer(stmt.value, scope)
        return False

    def _stmt_Assign(self, stmt: ast.Assign, scope: Scope) -> bool:
        value_t = self._infer(stmt.value, scope)
        for target in stmt.targets:
            self._bind_target(target, value_t, scope)
        return False

    def _stmt_AnnAssign(self, stmt: ast.AnnAssign, scope: Scope) -> bool:
        declared = resolve_annotation(stmt.annotation)
        if stmt.value is not None:
            value_t = self._infer(stmt.value, scope)
            if not is_assignable(value_t, declared):
                self.bag.error(
                    "E0002",
                    f"cannot assign value of type '{value_t}' to variable "
                    f"annotated as '{declared}'",
                    stmt,
                )
        if isinstance(stmt.target, ast.Name):
            scope.define(stmt.target.id, declared)
        return False

    def _stmt_AugAssign(self, stmt: ast.AugAssign, scope: Scope) -> bool:
        left = self._infer(stmt.target, scope)
        right = self._infer(stmt.value, scope)
        result = self._binop_result(stmt.op, left, right, stmt)
        if isinstance(stmt.target, ast.Name):
            scope.define(stmt.target.id, result)
        return False

    def _stmt_If(self, stmt: ast.If, scope: Scope) -> bool:
        self._infer(stmt.test, scope)
        then_scope = Scope(scope)
        then_term = self._check_block(stmt.body, then_scope)
        else_term = False
        if stmt.orelse:
            else_scope = Scope(scope)
            else_term = self._check_block(stmt.orelse, else_scope)
            # Merge variables defined in both branches into parent.
            self._merge_branches(scope, then_scope, else_scope)
        else:
            self._merge_branches(scope, then_scope, None)
        return then_term and else_term and bool(stmt.orelse)

    def _merge_branches(self, parent, then_s, else_s) -> None:
        if else_s is None:
            for name, t in then_s.vars.items():
                if parent.lookup(name) is not None:
                    existing = parent.lookup(name)
                    parent.define(name, join(existing, t))
            return
        names = set(then_s.vars) | set(else_s.vars)
        for name in names:
            in_then = name in then_s.vars
            in_else = name in else_s.vars
            if in_then and in_else:
                parent.define(name, join(then_s.vars[name], else_s.vars[name]))
            else:
                # Defined in only one branch: merge with prior or skip.
                existing = parent.lookup(name)
                branch_t = then_s.vars.get(name) or else_s.vars.get(name)
                if existing is not None:
                    parent.define(name, join(existing, branch_t))

    def _stmt_While(self, stmt: ast.While, scope: Scope) -> bool:
        self._infer(stmt.test, scope)
        body_scope = Scope(scope)
        self._check_block(stmt.body, body_scope)
        if stmt.orelse:
            self._check_block(stmt.orelse, Scope(scope))
        # `while True:` with no reachable `break` never falls through — it is a
        # terminator (like Rust's `loop {}` with type `!`). The function below
        # cannot fall off the end, so this counts as "all paths return".
        if self._is_truthy_const(stmt.test) and not self._has_break(stmt.body):
            return True
        return False

    @staticmethod
    def _is_truthy_const(test: ast.expr) -> bool:
        return isinstance(test, ast.Constant) and bool(test.value)

    @staticmethod
    def _has_break(body: list[ast.stmt]) -> bool:
        """True if a `break` belongs to *this* loop.

        Descends into ordinary compound statements (if/with/try) but never into
        nested loops, whose `break` targets the inner loop instead.
        """
        for stmt in body:
            if isinstance(stmt, ast.Break):
                return True
            if isinstance(stmt, (ast.For, ast.While, ast.AsyncFor)):
                continue  # break inside belongs to the nested loop
            if isinstance(stmt, ast.If):
                if Checker._has_break(stmt.body) or Checker._has_break(stmt.orelse):
                    return True
            elif isinstance(stmt, (ast.With, ast.AsyncWith)):
                if Checker._has_break(stmt.body):
                    return True
            elif isinstance(stmt, ast.Try):
                blocks = [stmt.body, stmt.orelse, stmt.finalbody]
                blocks += [h.body for h in stmt.handlers]
                if any(Checker._has_break(b) for b in blocks):
                    return True
        return False

    def _stmt_For(self, stmt: ast.For, scope: Scope) -> bool:
        iter_t = self._infer(stmt.iter, scope)
        elem_t = self._iter_elem(iter_t)
        body_scope = Scope(scope)
        self._bind_target(stmt.target, elem_t, body_scope)
        self._check_block(stmt.body, body_scope)
        if stmt.orelse:
            self._check_block(stmt.orelse, Scope(scope))
        # Loop vars escape into parent in Python.
        for name, t in body_scope.vars.items():
            scope.define(name, join(scope.lookup(name) or t, t))
        return False

    def _stmt_AsyncFor(self, stmt, scope):
        return self._stmt_For(stmt, scope)

    def _stmt_With(self, stmt: ast.With, scope: Scope) -> bool:
        for item in stmt.items:
            t = self._infer(item.context_expr, scope)
            if item.optional_vars is not None:
                self._bind_target(item.optional_vars, ANY, scope)
        return self._check_block(stmt.body, scope)

    _stmt_AsyncWith = _stmt_With

    def _stmt_Try(self, stmt: ast.Try, scope: Scope) -> bool:
        body_term = self._check_block(stmt.body, Scope(scope))
        if stmt.orelse:
            # try-body falls through to else; the pair terminates iff else does.
            body_term = self._check_block(stmt.orelse, Scope(scope))
        handlers_term = True
        for handler in stmt.handlers:
            h_scope = Scope(scope)
            if handler.name:
                h_scope.define(handler.name, ANY)
            if not self._check_block(handler.body, h_scope):
                handlers_term = False
        fin_term = False
        if stmt.finalbody:
            fin_term = self._check_block(stmt.finalbody, scope)
        # A finally that returns/raises terminates unconditionally. Otherwise
        # the try terminates when the normal path and every handler do.
        return fin_term or (body_term and handlers_term)

    def _stmt_Import(self, stmt: ast.Import, scope: Scope) -> bool:
        for alias in stmt.names:
            name = alias.asname or alias.name.split(".")[0]
            scope.define(name, ANY)
        return False

    def _stmt_ImportFrom(self, stmt: ast.ImportFrom, scope: Scope) -> bool:
        for alias in stmt.names:
            name = alias.asname or alias.name
            scope.define(name, ANY)
        return False

    def _stmt_Global(self, stmt, scope) -> bool:
        for name in stmt.names:
            if scope.lookup(name) is None:
                scope.define(name, ANY)
        return False

    _stmt_Nonlocal = _stmt_Global

    def _stmt_Delete(self, stmt: ast.Delete, scope: Scope) -> bool:
        for t in stmt.targets:
            self._infer(t, scope)
        return False

    def _stmt_Assert(self, stmt: ast.Assert, scope: Scope) -> bool:
        self._infer(stmt.test, scope)
        if stmt.msg:
            self._infer(stmt.msg, scope)
        return False

    # -- binding targets ------------------------------------------------
    def _bind_target(self, target: ast.expr, value_t: Type, scope: Scope) -> None:
        if isinstance(target, ast.Name):
            prev = scope.lookup(target.id)
            scope.define(target.id, value_t)
        elif isinstance(target, (ast.Tuple, ast.List)):
            elems = self._unpack(value_t, len(target.elts))
            for el, t in zip(target.elts, elems):
                if isinstance(el, ast.Starred):
                    self._bind_target(el.value, ListType(t), scope)
                else:
                    self._bind_target(el, t, scope)
        elif isinstance(target, ast.Starred):
            self._bind_target(target.value, ListType(value_t), scope)
        elif isinstance(target, (ast.Subscript, ast.Attribute)):
            # Evaluate the container expression for errors.
            self._infer(target, scope)

    def _unpack(self, t: Type, n: int) -> list[Type]:
        if isinstance(t, TupleType) and len(t.elems) == n:
            return list(t.elems)
        if isinstance(t, ListType):
            return [t.elem] * n
        if isinstance(t, AnyType):
            return [ANY] * n
        return [ANY] * n

    def _iter_elem(self, t: Type) -> Type:
        if isinstance(t, ListType):
            return t.elem
        if isinstance(t, StrType):
            return STR
        if isinstance(t, DictType):
            return t.key
        if isinstance(t, TupleType):
            return make_union(list(t.elems)) if t.elems else ANY
        return ANY

    # -- expression inference -------------------------------------------
    def _infer(self, node: ast.expr, scope: Scope) -> Type:
        m = getattr(self, "_expr_" + type(node).__name__, None)
        if m is None:
            return ANY
        return m(node, scope)

    def _expr_Constant(self, node: ast.Constant, scope: Scope) -> Type:
        v = node.value
        if isinstance(v, bool):
            return BOOL
        if isinstance(v, int):
            return INT
        if isinstance(v, float):
            return FLOAT
        if isinstance(v, str):
            return STR
        if v is None:
            return NONE
        return ANY

    def _expr_Name(self, node: ast.Name, scope: Scope) -> Type:
        t = scope.lookup(node.id)
        if t is None:
            if node.id in _BUILTIN_RETURNS or node.id in _KNOWN_NAMES:
                return ANY
            self.bag.error(
                "E0001",
                f"undefined name '{node.id}'",
                node,
                "this name is not defined in the current scope",
            )
            return ANY
        return t

    def _expr_List(self, node: ast.List, scope: Scope) -> Type:
        if not node.elts:
            return ListType(NEVER)
        ts = [self._infer(e, scope) for e in node.elts
              if not isinstance(e, ast.Starred)]
        for e in node.elts:
            if isinstance(e, ast.Starred):
                self._infer(e.value, scope)
        elem = ts[0] if ts else ANY
        for t in ts[1:]:
            elem = join(elem, t)
        return ListType(elem)

    def _expr_Tuple(self, node: ast.Tuple, scope: Scope) -> Type:
        return TupleType(tuple(self._infer(e, scope) for e in node.elts
                               if not isinstance(e, ast.Starred)))

    def _expr_Set(self, node: ast.Set, scope: Scope) -> Type:
        for e in node.elts:
            self._infer(e, scope)
        return ANY

    def _expr_Dict(self, node: ast.Dict, scope: Scope) -> Type:
        if not node.keys:
            return DictType(NEVER, NEVER)
        kt: Type = NEVER
        vt: Type = NEVER
        for k, v in zip(node.keys, node.values):
            if k is not None:
                kt = join(kt, self._infer(k, scope))
            if v is not None:
                vt = join(vt, self._infer(v, scope))
        return DictType(kt, vt)

    def _expr_JoinedStr(self, node, scope) -> Type:
        for v in node.values:
            if isinstance(v, ast.FormattedValue):
                self._infer(v.value, scope)
        return STR

    def _expr_BoolOp(self, node: ast.BoolOp, scope: Scope) -> Type:
        ts = [self._infer(v, scope) for v in node.values]
        result = ts[0]
        for t in ts[1:]:
            result = join(result, t)
        return result

    def _expr_UnaryOp(self, node: ast.UnaryOp, scope: Scope) -> Type:
        t = self._infer(node.operand, scope)
        if isinstance(node.op, ast.Not):
            return BOOL
        if isinstance(node.op, ast.USub) or isinstance(node.op, ast.UAdd):
            if isinstance(t, (IntType, FloatType, BoolType, AnyType)):
                return INT if isinstance(t, BoolType) else t
            self.bag.error(
                "E0006",
                f"unary operator cannot be applied to type '{t}'",
                node,
            )
            return ANY
        return t

    def _expr_BinOp(self, node: ast.BinOp, scope: Scope) -> Type:
        left = self._infer(node.left, scope)
        right = self._infer(node.right, scope)
        return self._binop_result(node.op, left, right, node)

    def _binop_result(self, op, left: Type, right: Type, node) -> Type:
        if isinstance(left, AnyType) or isinstance(right, AnyType):
            return ANY

        # Optional / Union operands: we cannot prove a real error without flow
        # narrowing (e.g. a preceding ``if x is not None``). Stay silent and
        # fall back to Any rather than emit a false positive. Concrete-typed
        # operands below are still checked strictly.
        if isinstance(left, (OptionalType, UnionType)) or isinstance(
            right, (OptionalType, UnionType)
        ):
            return ANY

        # ``Never`` comes from empty literals (``[]``/``{}``) whose element type
        # is not yet known; such containers are typically filled dynamically.
        # Don't flag operations on them.
        if isinstance(left, NeverType) or isinstance(right, NeverType):
            return ANY

        # String concatenation / repetition.
        if isinstance(op, ast.Add):
            if isinstance(left, StrType) and isinstance(right, StrType):
                return STR
            if isinstance(left, ListType) and isinstance(right, ListType):
                return ListType(join(left.elem, right.elem))
        if isinstance(op, ast.Mult):
            if isinstance(left, StrType) and isinstance(right, (IntType, BoolType)):
                return STR
            if isinstance(left, (IntType, BoolType)) and isinstance(right, StrType):
                return STR
            if isinstance(left, ListType) and isinstance(right, (IntType, BoolType)):
                return left
            if isinstance(right, ListType) and isinstance(left, (IntType, BoolType)):
                return right

        numeric = (IntType, FloatType, BoolType)
        if isinstance(left, numeric) and isinstance(right, numeric):
            if isinstance(op, ast.Div):
                return FLOAT
            if isinstance(left, FloatType) or isinstance(right, FloatType):
                return FLOAT
            return INT

        # Modulo on str is formatting.
        if isinstance(op, ast.Mod) and isinstance(left, StrType):
            return STR

        self.bag.error(
            "E0006",
            f"unsupported operand types for binary operator: "
            f"'{left}' and '{right}'",
            node,
        )
        return ANY

    def _expr_Compare(self, node: ast.Compare, scope: Scope) -> Type:
        left = self._infer(node.left, scope)
        operands = [left]
        for c in node.comparators:
            operands.append(self._infer(c, scope))
        # Comparison operators are overloadable (e.g. numpy/torch return an
        # array/tensor, not a bool). If any operand is Any, the result is Any.
        if any(isinstance(o, AnyType) for o in operands):
            return ANY
        return BOOL

    def _expr_IfExp(self, node: ast.IfExp, scope: Scope) -> Type:
        self._infer(node.test, scope)
        a = self._infer(node.body, scope)
        b = self._infer(node.orelse, scope)
        return join(a, b)

    def _expr_Call(self, node: ast.Call, scope: Scope) -> Type:
        func_t = self._infer(node.func, scope)

        # Builtin return-type shortcuts by name.
        if isinstance(node.func, ast.Name):
            name = node.func.id
            if name in _BUILTIN_RETURNS and scope.lookup(name) is None:
                for a in node.args:
                    self._infer(a, scope)
                for kw in node.keywords:
                    self._infer(kw.value, scope)
                return _BUILTIN_RETURNS[name]
            if name in ("list",) and scope.lookup(name) is None:
                for a in node.args:
                    self._infer(a, scope)
                return ListType(ANY)
            if name in ("dict",) and scope.lookup(name) is None:
                return DictType(ANY, ANY)

        arg_types = [self._infer(a, scope) for a in node.args]
        has_star = any(isinstance(a, ast.Starred) for a in node.args)
        for kw in node.keywords:
            self._infer(kw.value, scope)

        if isinstance(func_t, FunctionType):
            self._check_call(func_t, node, arg_types, has_star, scope)
            return func_t.ret

        if isinstance(func_t, AnyType):
            return ANY

        # Calling a clearly non-callable value.
        if isinstance(func_t, (IntType, FloatType, StrType, BoolType,
                               NoneType, ListType, DictType, TupleType)):
            self.bag.error(
                "E0007",
                f"value of type '{func_t}' is not callable",
                node,
            )
        return ANY

    @staticmethod
    def _narrowable(src: Type, dst: Type) -> bool:
        """True if ``src`` could become assignable to ``dst`` after flow
        narrowing we don't model. Optional[T]/Union members assignable to dst
        are treated as narrowable, so we suppress the error rather than guess.
        """
        if isinstance(src, OptionalType):
            return is_assignable(src.inner, dst) or isinstance(dst, AnyType)
        if isinstance(src, UnionType):
            return any(is_assignable(o, dst) for o in src.options)
        return False

    def _check_call(self, ft: FunctionType, node: ast.Call,
                    arg_types: list[Type], has_star: bool, scope: Scope) -> None:
        n_params = len(ft.params)
        n_required = n_params - ft.defaults
        n_pos = len(node.args)
        n_kw = len([k for k in node.keywords if k.arg])

        # Skip strict arity if *args used at call site.
        if has_star or any(k.arg is None for k in node.keywords):
            return

        # Method-style: first param is self/cls already bound? We treat module
        # functions only here, so count straight.
        total_supplied = n_pos + n_kw
        if total_supplied < n_required or (n_pos > n_params and not has_star):
            self.bag.error(
                "E0003",
                f"function expects {n_required if n_required == n_params else f'{n_required} to {n_params}'} "
                f"positional argument(s) but {total_supplied} were given",
                node,
            )
            return

        # Positional type checks.
        for i, at in enumerate(arg_types):  # noqa: E0004 below uses _narrowable
            if i >= n_params:
                break
            pt = ft.params[i]
            if not is_assignable(at, pt) and not self._narrowable(at, pt):
                pname = ft.param_names[i] if i < len(ft.param_names) else f"#{i+1}"
                self.bag.error(
                    "E0004",
                    f"argument '{pname}' expects type '{pt}' but got '{at}'",
                    node.args[i] if i < len(node.args) else node,
                )

        # Keyword type checks.
        name_index = {n: i for i, n in enumerate(ft.param_names)}
        for kw in node.keywords:
            if kw.arg in name_index:
                idx = name_index[kw.arg]
                pt = ft.params[idx]
                at = self._infer(kw.value, scope)
                if not is_assignable(at, pt) and not self._narrowable(at, pt):
                    self.bag.error(
                        "E0004",
                        f"argument '{kw.arg}' expects type '{pt}' but got '{at}'",
                        kw.value,
                    )

    def _expr_Subscript(self, node: ast.Subscript, scope: Scope) -> Type:
        container = self._infer(node.value, scope)
        # Index expression.
        is_slice = isinstance(node.slice, ast.Slice)
        if is_slice:
            for part in (node.slice.lower, node.slice.upper, node.slice.step):
                if part is not None:
                    self._infer(part, scope)
        else:
            idx_t = self._infer(node.slice, scope)

        if isinstance(container, AnyType):
            return ANY
        if isinstance(container, ListType):
            if is_slice:
                return container
            return container.elem
        if isinstance(container, StrType):
            return STR
        if isinstance(container, TupleType):
            if is_slice:
                return container
            return make_union(list(container.elems)) if container.elems else ANY
        if isinstance(container, DictType):
            return container.value
        # Non-subscriptable.
        if isinstance(container, (IntType, FloatType, BoolType, NoneType)):
            self.bag.error(
                "E0012",
                f"type '{container}' is not subscriptable",
                node,
            )
        return ANY

    def _expr_Attribute(self, node: ast.Attribute, scope: Scope) -> Type:
        self._infer(node.value, scope)
        return ANY

    def _expr_Lambda(self, node: ast.Lambda, scope: Scope) -> Type:
        inner = Scope(scope)
        for a in node.args.args:
            inner.define(a.arg, ANY)
        ret = self._infer(node.body, inner)
        return FunctionType(tuple(ANY for _ in node.args.args), ret)

    def _expr_ListComp(self, node: ast.ListComp, scope: Scope) -> Type:
        inner = self._comp_scope(node.generators, scope)
        elem = self._infer(node.elt, inner)
        return ListType(elem)

    def _expr_SetComp(self, node, scope) -> Type:
        inner = self._comp_scope(node.generators, scope)
        self._infer(node.elt, inner)
        return ANY

    def _expr_DictComp(self, node: ast.DictComp, scope: Scope) -> Type:
        inner = self._comp_scope(node.generators, scope)
        k = self._infer(node.key, inner)
        v = self._infer(node.value, inner)
        return DictType(k, v)

    def _expr_GeneratorExp(self, node, scope) -> Type:
        inner = self._comp_scope(node.generators, scope)
        self._infer(node.elt, inner)
        return ANY

    def _comp_scope(self, generators, scope: Scope) -> Scope:
        inner = Scope(scope)
        for gen in generators:
            iter_t = self._infer(gen.iter, inner)
            elem = self._iter_elem(iter_t)
            self._bind_target(gen.target, elem, inner)
            for cond in gen.ifs:
                self._infer(cond, inner)
        return inner

    def _expr_Starred(self, node: ast.Starred, scope: Scope) -> Type:
        return self._infer(node.value, scope)

    def _expr_Await(self, node: ast.Await, scope: Scope) -> Type:
        self._infer(node.value, scope)
        return ANY

    def _expr_NamedExpr(self, node: ast.NamedExpr, scope: Scope) -> Type:
        t = self._infer(node.value, scope)
        if isinstance(node.target, ast.Name):
            scope.define(node.target.id, t)
        return t

    def _expr_Slice(self, node, scope) -> Type:
        return ANY


def check_source(source: str, filename: str = "<input>") -> DiagnosticBag:
    return Checker(source, filename).check()

# ===== from pyaot/cli.py =====
"""Command-line interface for pyaot."""





def _iter_py_files(path: str) -> list[str]:
    """Expand a path into the list of .py files to check.

    A file yields itself; a directory is walked recursively for ``*.py``,
    skipping common noise dirs. Results are sorted for stable output.
    """
    if os.path.isfile(path):
        return [path]
    skip = {".git", "__pycache__", ".venv", "venv", ".mypy_cache",
            ".tox", "build", "dist", "node_modules"}
    found: list[str] = []
    for root, dirs, files in os.walk(path):
        dirs[:] = [d for d in dirs if d not in skip]
        for name in files:
            if name.endswith(".py"):
                found.append(os.path.join(root, name))
    return sorted(found)


def _check_one(path: str) -> tuple[int, int]:
    """Check a single file. Returns (n_errors, n_warnings)."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            source = f.read()
    except OSError as e:
        print(f"error: cannot read {path}: {e}", file=sys.stderr)
        return (1, 0)

    try:
        bag = check_source(source, path)
    except SyntaxError as e:
        print(f"error[E0000]: syntax error: {e.msg}")
        print(f"  --> {path}:{e.lineno}:{e.offset}")
        return (1, 0)

    if bag.diags:
        print(bag.render())
        print()
    n_err = len(bag.errors)
    return (n_err, len(bag.diags) - n_err)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="pyaot",
        description="Ahead-of-time static checker and compiler for Python "
        "(catch bugs before running, Rust-style).",
    )
    parser.add_argument(
        "path", help="Python source file or directory to check/compile"
    )
    parser.add_argument(
        "--quiet", "-q", action="store_true", help="only print on errors"
    )
    parser.add_argument(
        "--emit-c", action="store_true",
        help="emit generated C to stdout (subset only)",
    )
    parser.add_argument(
        "-o", "--output", metavar="BIN",
        help="compile to a native executable at BIN via the C backend",
    )
    args = parser.parse_args(argv)

    if not os.path.exists(args.path):
        print(f"error: no such file or directory: {args.path}", file=sys.stderr)
        return 2

    # Directory mode: check every .py file, aggregate results. Codegen flags
    # only make sense for a single file.
    if os.path.isdir(args.path):
        if args.emit_c or args.output:
            print("error: --emit-c/-o require a single file, not a directory",
                  file=sys.stderr)
            return 2
        files = _iter_py_files(args.path)
        if not files:
            print(f"pyaot: no .py files found under {args.path}")
            return 0
        total_err = total_warn = 0
        bad_files = 0
        for path in files:
            n_err, n_warn = _check_one(path)
            total_err += n_err
            total_warn += n_warn
            if n_err:
                bad_files += 1
        print(f"pyaot: checked {len(files)} file(s) — "
              f"{total_err} error(s) in {bad_files} file(s), "
              f"{total_warn} warning(s)")
        return 1 if total_err else 0

    # Single-file mode.
    try:
        with open(args.path, "r", encoding="utf-8") as f:
            source = f.read()
    except OSError as e:
        print(f"error: cannot read {args.path}: {e}", file=sys.stderr)
        return 2

    # 1. Static checking (always runs first, like Rust's borrow/type check).
    try:
        bag = check_source(source, args.path)
    except SyntaxError as e:
        print(f"error[E0000]: syntax error: {e.msg}")
        print(f"  --> {args.path}:{e.lineno}:{e.offset}")
        return 1

    if bag.diags:
        print(bag.render())
        print()

    n_err = len(bag.errors)
    n_warn = len(bag.diags) - n_err
    if n_err:
        print(f"pyaot: {n_err} error(s), {n_warn} warning(s) — compilation aborted")
        return 1

    # 2. Optional codegen (only if checking passed).
    if args.emit_c or args.output:
        try:
            c_source = compile_to_c(source, args.path)
        except UnsupportedError as e:
            print(f"error[E0100]: C backend: {e}")
            return 1

        if args.emit_c:
            sys.stdout.write(c_source)
            return 0

        return _build(c_source, args.output)

    if not args.quiet:
        print(f"pyaot: check passed ({n_warn} warning(s))")
    return 0


def _build(c_source: str, out_path: str) -> int:
    with tempfile.NamedTemporaryFile("w", suffix=".c", delete=False) as tf:
        tf.write(c_source)
        c_file = tf.name
    try:
        cc = os.environ.get("CC", "cc")
        proc = subprocess.run(
            [cc, "-O2", "-o", out_path, c_file, "-lm"],
            capture_output=True, text=True,
        )
        if proc.returncode != 0:
            print("error[E0101]: C compilation failed:")
            print(proc.stderr)
            return 1
        print(f"pyaot: compiled -> {out_path}")
        return 0
    finally:
        os.unlink(c_file)


if __name__ == "__main__":
    sys.exit(main())
