        start, stop, step = rng
        if step.startswith("-") or step.lstrip("-").isdigit() and int(step) < 0:
            cmp = ">"
        else:
            cmp = "<"
        self.emit(
            f"for ({var} = {start}; {var} {cmp} {stop}; {var} += {step}) {{"
