"""Type system for the pyaot ahead-of-time checker/compiler.

Types are immutable value objects with structural equality. They model a
statically-typed subset of Python. ``Any`` is the escape hatch and is
compatible with everything (gradual typing).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional


class Type:
    """Base class for all types."""

    def __str__(self) -> str:  # pragma: no cover - overridden
        return self.__class__.__name__

    def __repr__(self) -> str:
        return str(self)


@dataclass(frozen=True)
class AnyType(Type):
    def __str__(self) -> str:
        return "Any"


@dataclass(frozen=True)
class NoneType(Type):
    def __str__(self) -> str:
        return "None"


@dataclass(frozen=True)
class IntType(Type):
    def __str__(self) -> str:
        return "int"


@dataclass(frozen=True)
class FloatType(Type):
    def __str__(self) -> str:
        return "float"


@dataclass(frozen=True)
class BoolType(Type):
    def __str__(self) -> str:
        return "bool"


@dataclass(frozen=True)
class StrType(Type):
    def __str__(self) -> str:
        return "str"


@dataclass(frozen=True)
class NeverType(Type):
    """The type of expressions that never produce a value (e.g. raise)."""

    def __str__(self) -> str:
        return "Never"


@dataclass(frozen=True)
class ListType(Type):
    elem: Type

    def __str__(self) -> str:
        return f"list[{self.elem}]"


@dataclass(frozen=True)
class DictType(Type):
    key: Type
    value: Type

    def __str__(self) -> str:
        return f"dict[{self.key}, {self.value}]"


@dataclass(frozen=True)
class TupleType(Type):
    elems: tuple[Type, ...]

    def __str__(self) -> str:
        inner = ", ".join(str(e) for e in self.elems)
        return f"tuple[{inner}]"


@dataclass(frozen=True)
class OptionalType(Type):
    """``Optional[T]`` == ``T | None``."""

    inner: Type

    def __str__(self) -> str:
        return f"Optional[{self.inner}]"


@dataclass(frozen=True)
class UnionType(Type):
    options: tuple[Type, ...]

    def __str__(self) -> str:
        return " | ".join(str(o) for o in self.options)


@dataclass(frozen=True)
class FunctionType(Type):
    params: tuple[Type, ...]
    ret: Type
    param_names: tuple[str, ...] = ()
    defaults: int = 0  # number of trailing params that have defaults
    has_vararg: bool = False   # function declares *args
    has_kwarg: bool = False    # function declares **kwargs
    required_kwonly: tuple[str, ...] = ()  # keyword-only params w/o defaults

    def __str__(self) -> str:
        ps = ", ".join(str(p) for p in self.params)
        return f"({ps}) -> {self.ret}"


# Singletons for the common ground types.
ANY = AnyType()
NONE = NoneType()
INT = IntType()
FLOAT = FloatType()
BOOL = BoolType()
STR = StrType()
NEVER = NeverType()


def is_any(t: Type) -> bool:
    return isinstance(t, AnyType)


def make_optional(t: Type) -> Type:
    if isinstance(t, OptionalType):
        return t
    if isinstance(t, NoneType):
        return t
    return OptionalType(t)


def make_union(options: list[Type]) -> Type:
    """Build a normalized union: flatten, dedup, collapse singletons."""
    flat: list[Type] = []

    def add(x: Type) -> None:
        if isinstance(x, UnionType):
            for o in x.options:
                add(o)
        elif isinstance(x, OptionalType):
            add(x.inner)
            add(NONE)
        else:
            if x not in flat:
                flat.append(x)

    for o in options:
        add(o)

    if len(flat) == 1:
        return flat[0]
    # Collapse T | None into Optional[T] when exactly two members.
    if len(flat) == 2 and NONE in flat:
        other = flat[0] if flat[1] == NONE else flat[1]
        return OptionalType(other)
    return UnionType(tuple(flat))

