"""Resolve Python annotation AST nodes into our Type objects."""

from __future__ import annotations

import ast

from .types import (
    ANY,
    BOOL,
    FLOAT,
    INT,
    NONE,
    STR,
    DictType,
    ListType,
    OptionalType,
    TupleType,
    Type,
    make_optional,
    make_union,
)

_SIMPLE = {
    "int": INT,
    "float": FLOAT,
    "bool": BOOL,
    "str": STR,
    "None": NONE,
    "Any": ANY,
    "object": ANY,
}


def resolve_annotation(node: ast.expr | None) -> Type:
    """Best-effort: unknown annotations resolve to Any."""
    if node is None:
        return ANY

    if isinstance(node, ast.Name):
        return _SIMPLE.get(node.id, ANY)

    if isinstance(node, ast.Constant):
        if node.value is None:
            return NONE
        if isinstance(node.value, str):
            # Forward-ref string, e.g. "int"; try to parse it.
            try:
                inner = ast.parse(node.value, mode="eval").body
                return resolve_annotation(inner)
            except SyntaxError:
                return ANY
        return ANY

    if isinstance(node, ast.Subscript):
        return _resolve_subscript(node)

    # PEP 604 unions: int | None
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitOr):
        left = resolve_annotation(node.left)
        right = resolve_annotation(node.right)
        return make_union([left, right])

    return ANY


def _base_name(node: ast.expr) -> str:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    return ""


def _resolve_subscript(node: ast.Subscript) -> Type:
    base = _base_name(node.value).lower()
    sl = node.slice

    if base == "list":
        return ListType(resolve_annotation(sl))
    if base == "dict":
        if isinstance(sl, ast.Tuple) and len(sl.elts) == 2:
            return DictType(
                resolve_annotation(sl.elts[0]), resolve_annotation(sl.elts[1])
            )
        return DictType(ANY, ANY)
    if base == "tuple":
        if isinstance(sl, ast.Tuple):
            return TupleType(tuple(resolve_annotation(e) for e in sl.elts))
        return TupleType((resolve_annotation(sl),))
    if base == "optional":
        return make_optional(resolve_annotation(sl))
    if base == "union":
        if isinstance(sl, ast.Tuple):
            return make_union([resolve_annotation(e) for e in sl.elts])
        return resolve_annotation(sl)
    return ANY

